def _fget(name: str) -> List[float]:
    for n, v in FEXP:
        if n == name:
            return v
    raise ValueError("missing " + name)


def _sget(name: str) -> List[str]:
    for n, v in SEXP:
        if n == name:
            return v
    raise ValueError("missing " + name)


def _flat(got) -> List[float]:
    g = List[float]()
    a = np.asarray(got, dtype=float).ravel()
    for i in range(a.shape[0]):
        g.append(float(a[i]))
    return g


def check(name: str, got, rtol: float = 1e-7, atol: float = 1e-15):
    want = _fget(name)
    g = _flat(got)
    ok = len(g) == len(want)
    if ok:
        for i in range(len(want)):
            if np.isnan(want[i]):
                if not np.isnan(g[i]):
                    ok = False
            elif abs(g[i] - want[i]) > atol + rtol * abs(want[i]):
                ok = False
    if not ok:
        print("TEST FAILED:", name, g[:12], want[:12], len(g), len(want))


def checks(name: str, got):
    want = _sget(name)
    g = [str(v) for v in got]
    if g != want:
        print("TEST FAILED:", name, g, want)



def V(x):
    return x.__val__()


def TS(x):
    return x.__val__()


def mk(nch: int, n: int, k: float):
    out = np.empty((nch, n))
    for i in range(nch):
        for j in range(n):
            out[i, j] = np.sin(0.05 * (i + 1) * j + k) + 0.3 * np.cos(0.31 * j * (i + 2) + 0.5 * i) + 0.2 * np.sin(2.0 * j)
    return out


x = mk(3, 1200, 0.2)
sf = 250.0
# IIR notch
check("notch_iir", mne.filter.notch_filter(x, sf, 50.0, method='iir')[:, 300:303], 1e-6, 1e-12)
check("notch_iir_w", mne.filter.notch_filter(x, sf, 60.0, notch_widths=4.0, trans_bandwidth=2.0, method='iir')[:, 500:502], 1e-6, 1e-12)
r = mne.io.RawArray(x * 1e-6, mne.create_info(['a', 'b', 'c'], sf, 'eeg'))
r.notch_filter(50.0, method='iir')
check("raw_notch_iir", r.get_data()[:, 400:402], 1e-6, 1e-18)

# minimum phase FIR
h = mne.filter.create_filter(None, sf, None, 40.0, phase='minimum-half')
check("cf_minhalf_lp", [h.shape[0], h[0], h[5], h[20]], 1e-6, 1e-12)
h = mne.filter.create_filter(None, sf, 5.0, 40.0, phase='minimum')
check("cf_min_bp", [h.shape[0], h[0], h[5], h[20]], 1e-3, 1e-6)
