h = mne.filter.create_filter(None, sf, 5.0, 40.0, phase='minimum-half')
check("cf_minhalf", [h.shape[0], h[0], h[5], h[20]], 1e-3, 1e-6)
h = mne.filter.create_filter(None, sf, None, 30.0, phase='zero-double', fir_window='blackman')
check("cf_zd", [h.shape[0], h[10], h[h.shape[0] // 2]], 1e-8, 1e-14)
check("fd_min", mne.filter.filter_data(x, sf, None, 40.0, phase='minimum')[:, 400:403], 1e-6, 1e-12)
check("fd_hann_firwin2", mne.filter.filter_data(x, sf, 4.0, 45.0, fir_window='hann', fir_design='firwin2')[:, 400:403], 1e-6, 1e-12)

# raw resample with events
d = mk(3, 1000, 0.1) * 1e-6
d = np.vstack([d, np.zeros((1, 1000))])
d[3, 100] = 1
d[3, 400] = 2
info = mne.create_info(['a', 'b', 'c', 'STI'], 100., ['eeg', 'eeg', 'eeg', 'stim'])
rr = mne.io.RawArray(d, info)
ev = np.array([[100, 0, 1], [400, 0, 2], [999, 0, 1]])
